function storePhoto(file,key){if(!file)return;if(!/^image\//i.test(file.type||"")){$("personalizeNote").textContent="Please choose an image file.";return;}var reader=new FileReader();reader.onerror=function(){$("personalizeNote").textContent="I could not read that picture. Try another one.";};reader.onload=function(){var image=new Image();image.onerror=reader.onerror;image.onload=function(){var scale=Math.min(1,900/Math.max(image.width,image.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext("2d").drawImage(image,0,0,canvas.width,canvas.height);var prior=state.photos[key];state.photos[key]=canvas.toDataURL("image/jpeg",.84);if(save()){applyPhotos();$("personalizeNote").textContent="Your picture is saved in this browser.";}else{state.photos[key]=prior;$("personalizeNote").textContent="That image is too large to save here. Try a smaller picture.";}};image.src=reader.result;};reader.readAsDataURL(file);}
