function startBuiltInMusic(mode){try{var AudioCtor=window.AudioContext||window.webkitAudioContext;if(!AudioCtor)return Promise.resolve(false);musicCtx=musicCtx||new AudioCtor();if(!musicGain){musicGain=musicCtx.createGain();musicGain.gain.value=.72;musicGain.connect(musicCtx.destination);}var resumed=musicCtx.resume();function activate(){if(state.musicMode!==mode||musicCtx.state==="suspended")return false;if(musicPlaying)return true;musicGain.gain.setTargetAtTime(Number($("musicVolume").value||28)/60,musicCtx.currentTime,.2);musicStep=0;musicPlaying=true;musicTick();setMusicButton(true);return true;}if(musicCtx.state!=="suspended")return Promise.resolve(activate());return Promise.resolve(resumed).then(activate).catch(function(){return false;});}catch(e){return Promise.resolve(false);}}function setMusicPreset(mode){if(mode==="custom"){$("musicFile").value="";$("musicPreset").value=state.musicMode;$("musicFile").click();return;}var player=$("backgroundMusic");player.pause();if(musicUrl){URL.revokeObjectURL(musicUrl);musicUrl=null;player.src="music/romantic-background.mp3";}stopBuiltInMusic();state.musicMode=mode;save();if(mode==="off"){autoMusicNeedsGesture=false;setMusicButton(false);$("personalizeNote").textContent="Quiet sky is selected. Your pictures and choices are saved only in this browser.";return;}autoMusicNeedsGesture=true;$("personalizeNote").textContent="Trying to start your saved soundtrack. If your browser requires a tap, it will begin with your first tap or key press.";startBuiltInMusic(mode).then(function(started){if(state.musicMode!==mode)return;if(started){autoMusicNeedsGesture=false;$("personalizeNote").textContent="A gentle original soundtrack is playing. Choose Quiet sky to stop it.";}else{$("personalizeNote").textContent="Your soundtrack is ready. Your browser will start it with your first tap or key press.";}});}function updateMusicVolume(){var v=Number($("musicVolume").value||28)/60;if(musicGain&&musicCtx&&musicPlaying)musicGain.gain.setTargetAtTime(v,musicCtx.currentTime,.12);if($("backgroundMusic").src.indexOf("blob:")===0||$("backgroundMusic").src.indexOf("romantic-background.mp3")>=0)$("backgroundMusic").volume=v;}
