function drawQueens(a){var cols=Array(8).fill(-1);a.innerHTML='<div class="game-mark">♛</div><h3>Place all eight queens</h3><p>One queen per row. No two may share a column or diagonal.</p><p class="memory-stats">Queens placed: <b id="queenCount">0</b>/8</p><div class="expert-board" id="queenBoard"></div><div class="inline-actions"><button type="button" class="small-action" id="resetQueens">Clear the board ↻</button></div>';function paint(){var board=$("queenBoard");board.innerHTML=Array.from({length:64},function(_,i){var r=Math.floor(i/8),c=i%8,cl="expert-square "+((r+c)%2?"dark":"light")+(cols[r]===c?" queen-placed":"");return '<button type="button" class="'+cl+' queen-square" data-queen="'+i+'" aria-label="Row '+(r+1)+", column "+String.fromCharCode(97+c)+(cols[r]===c?", queen":"")+'">'+(cols[r]===c?"♛":"")+'</button>';}).join("");board.querySelectorAll(".queen-square").forEach(function(b){b.onclick=function(){var i=Number(b.dataset.queen),r=Math.floor(i/8),c=i%8,old=cols[r];if(old===c){cols[r]=-1;}else{for(var rr=0;rr<8;rr++)if(rr!==r&&cols[rr]>=0&&(cols[rr]===c||Math.abs(rr-r)===Math.abs(cols[rr]-c))){msg("That square is attacked by another queen. Try a different column.",true);return;}cols[r]=c;}$("queenCount").textContent=cols.filter(function(x){return x>=0;}).length;msg("");paint();if(cols.every(function(x){return x>=0;}))win("Eight queens, no collisions. What a perfectly balanced constellation.");};});}$("resetQueens").onclick=function(){cols.fill(-1);$("queenCount").textContent="0";msg("");paint();};paint();}
